// Generated by crates/xtask from the Rust question model.
// Do not edit by hand; run ./build.sh (or cargo run -p xtask -- tsgen).

/**
 * How a response is judged, without stating what the answer is.
 *
 * Safe to send to a browser: a student can see that partial credit applies and
 * how a question is weighted, and still learn nothing about the answer.
 */
export type GradingDefinition =
  | {
      mode: "allOrNothing";
      points: number;
    }
  | {
      mode: "partialCredit";
      points: number;
    }
  | { mode: "ungraded" };
